import{_ as e,o,c as r,a3 as a}from"./chunks/framework.qCVWde4n.js";const g=JSON.parse('{"title":"换成自己的 key","description":"","frontmatter":{},"headers":[],"relativePath":"zh/own-key.md","filePath":"zh/own-key.md"}'),n={name:"zh/own-key.md"};function d(l,t,i,c,s,p){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="换成自己的-key" tabindex="-1">换成自己的 key <a class="header-anchor" href="#换成自己的-key" aria-label="Permalink to &quot;换成自己的 key&quot;">​</a></h1><p>nanoMuse 免费、非营利。它背后的模型要花钱，每个账号的起始额度由开发者出（应用里显示的是中继当前的数字）。额度用完以后，有两条路可以继续走，都不需要 nanoMuse 再提供什么：在某家模型服务商申请一把自己的 key，或者用你已经在付费的套餐——ChatGPT、Claude、Kimi——在应用里登录。</p><p>每个客户端读的都是同一份服务商清单，每家能做什么也写在里面：<strong>对话</strong>、<strong>动手</strong>（一个能看截图的模型）、<strong>画图</strong>（形象工作室）和<strong>视频</strong>（形象的短视频）。没有任何已配置的服务商能做的功能，就干脆不提供，只用一句话说明哪些服务商可以——什么都不会坏。</p><p>你的登录、邀请码和设备都不受影响：账号还是那个账号，换的只是模型服务商。用上自己的 key 或套餐之后，你说的话不再经过 nanoMuse Cloud。</p><h2 id="where-you-are-decides-who-comes-first" tabindex="-1">先看你在哪 <a class="header-anchor" href="#where-you-are-decides-who-comes-first" aria-label="Permalink to &quot;先看你在哪 {#where-you-are-decides-who-comes-first}&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>首选</th><th>一把 key 能做什么</th></tr></thead><tbody><tr><td>中国大陆</td><td><strong>阿里云百炼</strong></td><td>对话、动手、画图、生成视频——四样都在一把 key 下</td></tr><tr><td>海外</td><td><strong>OpenRouter</strong>，其次 <strong>OpenAI</strong></td><td>对话、动手、画图；生成视频目前只有百炼</td></tr></tbody></table><p>百炼只给中国大陆身份注册；海外用户一个 OpenRouter 账号就能用到几百个模型，按量付费。首选之外，下面的每一家都可以单独用，或者和另一家搭配——比如对话用 DeepSeek、画图用智谱。</p><p>对话模型和手的模型是两个设置：对话模型在模型选择里，手的模型在「手的模型」一行（手机：设置 → Hands；网页版 / 桌面版：连接）。手的模型必须能看图；App 里的手的模型列表只列能看图的。</p><h2 id="what-each-provider-covers" tabindex="-1">各家服务商能做什么 <a class="header-anchor" href="#what-each-provider-covers" aria-label="Permalink to &quot;各家服务商能做什么 {#what-each-provider-covers}&quot;">​</a></h2><p>对话 = 聊天；动手 = 看截图操作手机和电脑；画图 = 形象工作室的图片；视频 = 形象的短动画。</p><table tabindex="0"><thead><tr><th>服务商</th><th style="text-align:center;">对话</th><th style="text-align:center;">动手</th><th style="text-align:center;">画图</th><th style="text-align:center;">视频</th><th>地区</th><th>申请 key</th></tr></thead><tbody><tr><td>阿里云百炼</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td>中国大陆</td><td><a href="https://bailian.console.aliyun.com/?apiKey=1" target="_blank" rel="noreferrer">bailian.console.aliyun.com</a></td></tr><tr><td>DeepSeek</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>都可以</td><td><a href="https://platform.deepseek.com/api_keys" target="_blank" rel="noreferrer">platform.deepseek.com</a></td></tr><tr><td>Kimi（月之暗面）</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>都可以（国内 / 国际两个版本）</td><td><a href="https://platform.moonshot.cn/console/api-keys" target="_blank" rel="noreferrer">platform.moonshot.cn</a> · <a href="https://platform.kimi.ai/console" target="_blank" rel="noreferrer">platform.kimi.ai</a></td></tr><tr><td>智谱 GLM</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>中国大陆</td><td><a href="https://open.bigmodel.cn/usercenter/apikeys" target="_blank" rel="noreferrer">open.bigmodel.cn</a></td></tr><tr><td>硅基流动</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>中国大陆</td><td><a href="https://cloud.siliconflow.cn/account/ak" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a></td></tr><tr><td>火山方舟（豆包）</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>中国大陆</td><td><a href="https://console.volcengine.com/ark/region:ark+cn-beijing/apiKey" target="_blank" rel="noreferrer">console.volcengine.com</a></td></tr><tr><td>MiniMax</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>都可以（国内 / 国际两个版本）</td><td><a href="https://platform.minimaxi.com/user-center/basic-information/interface-key" target="_blank" rel="noreferrer">platform.minimaxi.com</a></td></tr><tr><td>OpenRouter</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>海外</td><td><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a></td></tr><tr><td>OpenAI</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>海外</td><td><a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">platform.openai.com</a></td></tr><tr><td>Anthropic Claude</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>海外</td><td><a href="https://platform.claude.com/settings/keys" target="_blank" rel="noreferrer">platform.claude.com</a></td></tr><tr><td>Google Gemini</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>海外</td><td><a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">aistudio.google.com</a></td></tr><tr><td>xAI Grok</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>海外</td><td><a href="https://console.x.ai" target="_blank" rel="noreferrer">console.x.ai</a></td></tr><tr><td>Groq</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>海外</td><td><a href="https://console.groq.com/keys" target="_blank" rel="noreferrer">console.groq.com</a></td></tr><tr><td>Mistral AI</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>海外</td><td><a href="https://console.mistral.ai/api-keys" target="_blank" rel="noreferrer">console.mistral.ai</a></td></tr><tr><td>Ollama / LM Studio / vLLM（本机）</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>都可以</td><td>不需要 key</td></tr></tbody></table><p>「视频」一栏只有百炼，是因为 nanoMuse 的视频生成走的是百炼的接口；其他家的视频模型用的是各自的任务接口，这一轮还没有接。「画图」一栏里，OpenRouter 走的是它的 Image API，模型例如 <code>openai/gpt-image-2</code>；Gemini 用 <code>gemini-2.5-flash-image</code>。</p><p>这张表来自仓库里的目录文件 <a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/llm/providers.json" target="_blank" rel="noreferrer"><code>nanomuse/llm/providers.json</code></a>——每个客户端、中继都读它，地址、默认模型和「能做什么」都在里面；表里的事实在 2026 年 10 月对照各家文档核过。</p><h2 id="making-a-key" tabindex="-1">怎么申请 key <a class="header-anchor" href="#making-a-key" aria-label="Permalink to &quot;怎么申请 key {#making-a-key}&quot;">​</a></h2><p>每家的步骤都是一样的三步：注册 → 控制台里创建 API key → 复制到 nanoMuse。<strong>key 只给 nanoMuse 用，不要发给任何人、不要贴到聊天里。</strong></p><ul><li><strong>阿里云百炼。</strong> 用阿里云账号登录 <a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">bailian.console.aliyun.com</a>（要实名认证），首次进入点「开通百炼服务」，再到 <a href="https://bailian.console.aliyun.com/?apiKey=1" target="_blank" rel="noreferrer">API-KEY 页</a> 创建；key 以 <code>sk-</code> 开头。新账号有一段时间的免费 token。建议在控制台设一个用量告警。</li><li><strong>DeepSeek。</strong> <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">platform.deepseek.com</a> 注册、充值、API Keys 里创建。地址 <code>https://api.deepseek.com/v1</code>。</li><li><strong>Kimi。</strong> 国内版在 <a href="https://platform.moonshot.cn/console/api-keys" target="_blank" rel="noreferrer">platform.moonshot.cn</a>，地址 <code>https://api.moonshot.cn/v1</code>；国际版在 <a href="https://platform.kimi.ai/console" target="_blank" rel="noreferrer">platform.kimi.ai</a>，地址 <code>https://api.moonshot.ai/v1</code>。两个版本的账号和 key 不通用。</li><li><strong>智谱 GLM。</strong> <a href="https://open.bigmodel.cn/usercenter/apikeys" target="_blank" rel="noreferrer">open.bigmodel.cn</a>，地址 <code>https://open.bigmodel.cn/api/paas/v4</code>。</li><li><strong>硅基流动。</strong> <a href="https://cloud.siliconflow.cn/account/ak" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a>，地址 <code>https://api.siliconflow.cn/v1</code>；模型 id 带厂商前缀，例如 <code>deepseek-ai/DeepSeek-V4-Flash</code>。</li><li><strong>火山方舟。</strong> <a href="https://console.volcengine.com/ark/region:ark+cn-beijing/apiKey" target="_blank" rel="noreferrer">console.volcengine.com</a>，先在方舟里开通要用的模型，再创建 key；地址 <code>https://ark.cn-beijing.volces.com/api/v3</code>。</li><li><strong>MiniMax。</strong> 国内版 <a href="https://platform.minimaxi.com/user-center/basic-information/interface-key" target="_blank" rel="noreferrer">platform.minimaxi.com</a>，地址 <code>https://api.minimaxi.com/v1</code>；国际版地址 <code>https://api.minimax.io/v1</code>。</li><li><strong>OpenRouter。</strong> <a href="https://openrouter.ai/" target="_blank" rel="noreferrer">openrouter.ai</a> 用 Google、GitHub 或邮箱登录，<em>Credits</em> 里充值，<em>Keys</em> 里创建；key 以 <code>sk-or-v1-</code> 开头。<em>Settings → Limits</em> 可以给 key 设每月上限。</li><li><strong>OpenAI。</strong> <a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">platform.openai.com</a>，地址 <code>https://api.openai.com/v1</code>。</li><li><strong>Anthropic。</strong> <a href="https://platform.claude.com/settings/keys" target="_blank" rel="noreferrer">platform.claude.com</a>。nanoMuse 直接用 Anthropic 的接口，不需要兼容层。</li><li><strong>Google Gemini。</strong> <a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">aistudio.google.com/apikey</a>，地址 <code>https://generativelanguage.googleapis.com/v1beta/openai</code>。</li><li><strong>xAI、Groq、Mistral。</strong> 各自的控制台创建 key；地址分别是 <code>https://api.x.ai/v1</code>、<code>https://api.groq.com/openai/v1</code>、<code>https://api.mistral.ai/v1</code>。</li></ul><p><strong>贴到 nanoMuse 里。</strong></p><ul><li>手机：额度用完时卡片上的「去设置」会打开预填好的服务商表单；或者 设置 → 服务商 → 添加，选服务商，贴 key，保存。</li><li>网页版 / 桌面版：额度卡片上的「去设置」会打开「连接」页并选好服务商；或者 连接 → 模型，点服务商，贴 key，保存。地址已经填好。</li><li>自己跑的运行时：在 <code>config.toml</code> 里写 <code>[llm] provider = &quot;bailian&quot;</code>（表里任一服务商的 id）加 <code>api_key</code>，地址和默认模型会从目录文件里补上；画图、生成视频用另一家，就加 <code>[image]</code> / <code>[video]</code> 一段（<a href="./configuration#image-and-video">configuration.md</a>）。</li></ul><p>保存后 nanoMuse 列出这把 key 能用的模型：对话选一个，手的模型选一个能看图的；想换形象，再到 连接 → 图像与视频模型 里选。每家的默认模型在目录文件里。</p><h2 id="sign-in-with-a-plan-you-already-pay-for" tabindex="-1">用你已经在付费的套餐登录 <a class="header-anchor" href="#sign-in-with-a-plan-you-already-pay-for" aria-label="Permalink to &quot;用你已经在付费的套餐登录 {#sign-in-with-a-plan-you-already-pay-for}&quot;">​</a></h2><p>有些套餐可以直接登录使用，不用申请 key：</p><table tabindex="0"><thead><tr><th>套餐</th><th>能做什么</th><th>哪里可以登录</th></tr></thead><tbody><tr><td><strong>ChatGPT</strong>（Plus / Pro / Team）</td><td>对话、动手</td><td>Android、iPhone、桌面版、网页版</td></tr><tr><td><strong>Claude</strong>（Pro / Max）</td><td>对话、动手</td><td>Android、iPhone</td></tr><tr><td><strong>Kimi</strong></td><td>对话、动手</td><td>Android、iPhone（设备码登录）</td></tr><tr><td><strong>OpenRouter</strong></td><td>对话、动手、画图</td><td>Android、iPhone（一键登录，key 自动回到 App）</td></tr></tbody></table><p>ChatGPT 登录走的是 OpenAI 自家 Codex 的授权流程（网页版 / 桌面版：连接 → 「或者用 ChatGPT 套餐登录」；手机：设置 → 服务商 → OpenAI → 登录）。登录后只有对话和动手——Codex 这条通道没有图像和视频接口；画图和生成视频仍要配一把 key。</p><p>在终端里也可以：<code>nanomuse chatgpt login</code> 打开登录页并等浏览器回来，<code>nanomuse chatgpt status</code> 看登录的是谁、什么时候过期，<code>nanomuse chatgpt logout</code> 忘掉它；然后在 <code>config.toml</code> 里写 <code>[llm] provider = &quot;chatgpt&quot;</code>（不用 <code>base_url</code>、<code>api_key</code>，<code>model</code> 留空就是 <code>gpt-5.6-sol</code>）。浏览器要能访问运行时所在机器的 1455 端口；运行时在别的机器上时，把浏览器最后停在的那个地址整条复制下来，贴给命令行的提示，或者 <code>POST /api/chatgpt/callback {&quot;url&quot;: …}</code>（<a href="./configuration#a-chatgpt-plan-instead-of-a-key">configuration.md</a>）。</p><p><strong>一句老实话。</strong> OpenAI 的条款只允许在它自家的 Codex 里使用 ChatGPT 套餐；其他应用曾被切断过这条路（OpenCode，2026 年 1 月）。哪天它不能用了，API key 仍然可以。</p><h2 id="when-the-provider-cannot-be-reached" tabindex="-1">服务商连不上的时候 <a class="header-anchor" href="#when-the-provider-cannot-be-reached" aria-label="Permalink to &quot;服务商连不上的时候 {#when-the-provider-cannot-be-reached}&quot;">​</a></h2><p>有些网络到不了 <code>chatgpt.com</code>（DNS 不解析、连接超时、TLS 失败、返回的是一张 HTML 拦截页），有些地区 OpenAI 直接拒绝（HTTP 403 <code>unsupported_country_region_territory</code>）。这时手机上的对话不再显示 socket 原文，而是一张卡片：发生了什么（「这个网络连不上 chatgpt.com」或「OpenAI 不向这个地区提供服务」）、能帮上忙的（这台手机上的 VPN；应用自己的代理，设置 → 网络；换一个服务商、用自己的 key）、一个「重试」按钮，原始错误收在「详情」里供提 issue 用。登录失效（401）显示「ChatGPT 登录已失效」和「重新登录」；套餐这几个小时的余量用完（429 且写明 usage limit）显示「ChatGPT 套餐暂时没有余量了」、OpenAI 自己的那句话和多久后恢复；其他 429 是「同时发出的请求太多」。自己的 key 遇到同样的网络问题，卡片一样出现，只是主机名换成那家服务商的。</p><p><strong>设置 → 网络 → 自有服务商的 HTTP 代理</strong>（Android 和 iPhone 都有）：主机、端口、可选的用户名和密码，默认关闭，只存在这台手机上。只有发往你用自己 key 添加的服务商和 ChatGPT 套餐的请求走它；nanoMuse Cloud、你的电脑和局域网从不经过它。页面上有一行「测试」，通过这个代理抓一次 <code>https://chatgpt.com/</code>，告诉你通没通、多少毫秒。同一个设置在每个应用里都放在存 key 的地方：手机在服务商表单里；桌面版在<strong>设置 → nanoMuse Cloud → 网络</strong>，一个地址（<code>http://host:port</code> 或 <code>socks5://host:port</code>），应用在下次启动时写进它的 Host 进程——这一行下面有「立即重启」——于是每把自己的 key、ChatGPT 登录、手的运行时和这个应用对外发出的其他请求都走它，nanoMuse 云端永远不走（<a href="./desktop">desktop.md</a>）；网页版在自有 key 表单里有「代理」一栏；运行时是 <code>config.toml</code> 里的 <code>[llm] proxy</code>（<a href="./configuration#llm">configuration.md</a>）。</p><h2 id="local-models" tabindex="-1">本机模型 <a class="header-anchor" href="#local-models" aria-label="Permalink to &quot;本机模型 {#local-models}&quot;">​</a></h2><p>Ollama、LM Studio、vLLM 跑在自己电脑上的模型也能用：在「连接」里选对应的预设，地址默认是本机端口（<code>http://127.0.0.1:11434/v1</code>、<code>:1234</code>、<code>:8000</code>），不需要 key。它们算「对话」；手的模型要能看图，本机跑一个多模态模型（例如 Ollama 的 <code>qwen3-vl</code>）再在「手的模型」里手填 id 即可。画图和视频需要上面表里的一家。</p><h2 id="any-other-openai-compatible-endpoint" tabindex="-1">其他 OpenAI 兼容服务 <a class="header-anchor" href="#any-other-openai-compatible-endpoint" aria-label="Permalink to &quot;其他 OpenAI 兼容服务 {#any-other-openai-compatible-endpoint}&quot;">​</a></h2><p>任何 OpenAI 兼容接口都能填，选「自定义」：</p><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>地址（Base URL）</td><td>服务商给的地址，通常以 <code>/v1</code> 结尾</td></tr><tr><td>API key</td><td>服务商控制台里创建的 key（本机服务可以留空）</td></tr><tr><td>模型</td><td>保存后从列表里选；列不出来就手填服务商文档里的模型 id</td></tr></tbody></table><p>自定义接口能做什么由你来说：nanoMuse 会把它当作对话；手的模型、图片模型、视频模型各自填了 id 才算有。</p>',34)])])}const m=e(n,[["render",d]]);export{g as __pageData,m as default};
